<h1>Matching tools</h1>
<section class="card"><h2>Run matching for a user</h2><form method="post" action="/admin/matches/run" class="grid two"><?= csrf_field() ?><label>User <select name="user_id" required><?php foreach ($users as $member): ?><option value="<?= (int)$member['id'] ?>"><?= e($member['first_name'].' '.$member['last_name'].' — '.$member['email']) ?></option><?php endforeach; ?></select></label><label class="check"><input type="checkbox" name="recalculate" value="1"> Recalculate existing pairs</label><button class="button">Run matching</button></form></section>
<section class="card table-wrap"><h2>Recent matches</h2><table><thead><tr><th>ID</th><th>Users</th><th>Status</th><th>Score</th><th>Confidence</th><th>Admin actions</th></tr></thead><tbody><?php foreach ($matches as $match): ?><tr><td><?= (int)$match['id'] ?></td><td><?= e($match['user_one_name']) ?> ↔ <?= e($match['user_two_name']) ?></td><td><?= e($match['match_status']) ?></td><td><?= (int)round((float)$match['compatibility_score']) ?>%</td><td><?= (int)round((float)$match['confidence_score']) ?>%</td><td><a href="/admin/matches?match_id=<?= (int)$match['id'] ?>">View scores</a><form method="post" action="/admin/matches/reset" class="inline"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$match['id'] ?>"><label class="check"><input type="checkbox" name="clear_actions" value="1"> clear actions</label><button>Reset</button></form><form method="post" action="/admin/matches/recalculate" class="inline"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$match['id'] ?>"><button>Recalculate</button></form></td></tr><?php endforeach; ?></tbody></table></section>
<?php if ($selectedMatchId): ?><section class="card"><h2>Explanation for match #<?= (int)$selectedMatchId ?></h2><?php if ($explanation): ?><p><strong>Why:</strong> <?= e($explanation['why_matched']) ?></p><p><strong>Strengths:</strong><br><?= nl2br(e($explanation['strongest_points'])) ?></p><p><strong>Cautions:</strong><br><?= nl2br(e($explanation['caution_points'])) ?></p><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Type</th><th>Score</th><th>Weight</th><th>Details</th></tr></thead><tbody><?php foreach ($scores as $score): ?><tr><td><?= e($score['score_type']) ?></td><td><?= e((string)$score['score_value']) ?></td><td><?= e((string)$score['weight']) ?></td><td><?= e($score['details']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="card table-wrap"><h2>Blocked pairs</h2><table><thead><tr><th>Blocker</th><th>Blocked</th><th>Source</th><th>Reason</th><th>Created</th></tr></thead><tbody><?php foreach ($blockedPairs as $block): ?><tr><td><?= e($block['blocker_name']) ?></td><td><?= e($block['blocked_name']) ?></td><td><?= e($block['source']) ?></td><td><?= e($block['reason_text']) ?></td><td><?= e($block['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></section>
